#!/bin/bash
# GENERATED by gen_core_kit_legacy.py: run one kits_repin core kit through ORFS in docker.  Fail-closed gates (CP1-R10):
# sdc_lint.py against the image's liberty time_unit BEFORE synth, face_guard (face_guard_core.py) on the RAW Yosys netlist
# (1_2_yosys.v, COORD 00:32) and on the post-synth netlist right AFTER synth; either failing stops the kit.  Then finish (route + fill + RCX), generate_abstract, the pin audit
# of the routed ODB against the plan pins, and corners.tcl STA at TT / FF (+ timing models).
#   run_kit.sh KITDIR [GOAL=finish] [MEM_GB=32] [CPUS=16]
set -uo pipefail
K=$(cd "$1" && pwd); GOAL=${2:-finish}; MEM=${3:-32}; CPUS=${4:-16}
IMAGE=${OT_ORFS_IMAGE:-openroad/orfs:asap7lock}
DOCKER=${OT_DOCKER:-docker}
NAME=klegacy-$(basename "$K")-$$
TOP=$(sed -n 's/^export DESIGN_NAME = //p' "$K/config.mk")
SKIP=$(cat "$K/face_guard_skip.txt")
echo "image $IMAGE $($DOCKER image inspect --format '{{.Id}}' $IMAGE) host $(hostname) start $(date -Is)" > "$K/image.txt"
