# EQUIVALENT stops the route where it is and the kit waits for the LEC verdict.  OT_LEC_ASYNC=0 = the inline LEC.
LECA=
if { [ "${OT_LEC_ASYNC:-1}" != 0 ] || [ -f "$K/lec_async.on" ] || [ -f "$K/lec_async.identity" ]; } && [ -f "$K/lec_async.sh" ] && [ -f "$K/lec.py" ]; then
  LECA=1; bash "$K/lec_async.sh" start "$K" "$NAME" "$IMAGE" "$MEM" "$CPUS" "$DOCKER" "$GOAL" || exit $?
fi
$DOCKER run --rm --name "$NAME" --cpus="$CPUS" --memory="${MEM}g" --memory-swap="${MEM}g" -v "$K":/work \
  -e HUID=$(id -u) -e HGID=$(id -g) -w /OpenROAD-flow-scripts/flow "$IMAGE" bash -lc "source /OpenROAD-flow-scripts/env.sh >/dev/null 2>&1; \
  M='make DESIGN_CONFIG=/work/config.mk WORK_HOME=/work/run FLOW_VARIANT=base NUM_CORES=$CPUS'; rc=0; \
  python3 -I /work/rtl_lint.py /work > /work/rtl_lint.log 2>&1; rc=\$?; tail -3 /work/rtl_lint.log; if [ \$rc != 0 ]; then echo 'FAIL_PREFLOOR lint (implicit / undriven nets, missing module or port; or NOT RUN), see rtl_lint.json' | tee -a /work/FAIL_PREFLOOR; rc=8; fi; \
  if [ \$rc = 0 ]; then python3 -I /work/sdc_lint.py /work --liberty \$(ls /OpenROAD-flow-scripts/flow/platforms/asap7/lib/NLDM/asap7sc7p5t_*RVT_*.lib* 2>/dev/null | grep -v FAKE) > /work/sdc_lint.log 2>&1; rc=\$?; tail -3 /work/sdc_lint.log; fi; \
  if [ \$rc = 0 ]; then \$M synth; rc=\$?; fi; \
  N=\$(ls /work/run/results/asap7/*/base/1_synth.v 2>/dev/null | tail -1); \
  RAW=\$(ls /work/run/results/asap7/*/base/1_2_yosys.v 2>/dev/null | tail -1); \
  if [ \$rc = 0 ]; then python3 -I /work/face_guard_core.py \$RAW $TOP '$SKIP' /work/pins.json /work/face_guard_raw.json > /work/face_guard_raw.log 2>&1; rc=\$?; cat /work/face_guard_raw.log; \
    if [ \$rc != 0 ]; then echo 'FACE_GUARD RAW FAIL (COORD 00:32: stop before floorplan)'; fi; fi; \
  if [ \$rc = 0 ]; then python3 -I /work/face_guard_core.py \$N $TOP '$SKIP' /work/pins.json /work/face_guard.json; rc=\$?; \
    if [ \$rc != 0 ] && [ -f /work/face_guard_continue ]; then echo 'FACE_GUARD FAIL: PATHFINDING physical run continues (face_guard_continue), FAIL recorded'; rc=0; fi; fi; \
  if [ \$rc = 0 ] && { [ -f /work/lec_async.on ] || [ -f /work/lec_async.identity ]; }; then bash /work/lec_async.sh check-synth /work '$NAME'; rc=\$?; fi; if [ \$rc = 0 ] && { [ -f /work/lec_async.on ] || [ -f /work/lec_async.identity ]; } && [ ! -f /work/lec_async.ready ]; then printf 'nz\\npython3 -I /work/legacy_gate.py /work lec --netlist %s\\n' \$RAW > /work/lec_async.ready; echo 'LEC_ASYNC: pre-route LEC runs beside the flow (lec_async.log)'; fi; if [ \$rc = 0 ] && [ ! -f /work/lec_async.on ] && [ ! -f /work/lec_async.identity ]; then python3 -I /work/legacy_gate.py /work lec --netlist \$RAW; rc=\$?; fi; \
  if [ \$rc = 0 ] && [ -f /work/reg_fanout_gate.py ]; then python3 -I /work/reg_fanout_gate.py \$N --top $TOP --out /work/reg_fanout.json > /work/reg_fanout.log 2>&1; rc=\$?; head -12 /work/reg_fanout.log; if [ \$rc != 0 ]; then echo 'FAIL_PREFLOOR reg_fanout (register > 64 data loads: merged replicas; or NOT RUN), see reg_fanout.json' | tee -a /work/FAIL_PREFLOOR; rc=7; fi; fi; \
  HM=\$(sed -n 's/^export OT_HOLD_FF_MARGIN = //p' /work/config.mk); VF=\$(sed -n 's/^export OT_VCLK_FF = //p' /work/config.mk); MM=\$(grep -c '^override export OT_HOLD_MM = 1' /work/config.mk); if [ \$rc = 0 ] && [ -n \"\$HM\" ] && [ -n \"\$VF\" ] && { [ $GOAL = finish ] || [ $GOAL = route ] || [ $GOAL = grt ]; }; then python3 -I /work/kit_modes.py check /work --step cts > /work/kit_modes_cts.log 2>&1; km=\$?; cat /work/kit_modes_cts.log; if [ \$km != 0 ]; then if grep -q '^export OT_KIT_MODES_STRICT = 1' /work/config.mk; then echo 'FAIL_PREFLOOR kit_modes cts (one timing mode per corner, strict)' | tee -a /work/FAIL_PREFLOOR; rc=9; else echo 'KIT_MODES ADVISORY cts: hold repaired in a single mode over tc+bc (QoR only)'; fi; fi; fi; if [ \$rc = 0 ] && grep -q '^override export OT_HOLD_MM = 1' /work/config.mk; then python3 -I /work/orfs_hold_mm.py /OpenROAD-flow-scripts/flow/scripts /work/orfs_hold_mm.tcl > /work/orfs_hold_mm.log 2>&1 || { cat /work/orfs_hold_mm.log; echo 'KIT_MODES FAIL orfs_hold_mm patch'; rc=9; }; fi; if [ \$rc = 0 ] && [ -n \"\$HM\" ] && [ -n \"\$VF\" ] && { [ $GOAL = finish ] || [ $GOAL = route ] || [ $GOAL = grt ]; }; then \$M cts; rc=\$?; if [ \$rc != 0 ]; then echo 'CTS (kit corners) before the FF-only GRT step failed'; fi; fi; if [ \$rc = 0 ] && [ -n \"\$HM\" ] && [ -n \"\$VF\" ] && [ \$MM != 0 ] && { [ $GOAL = finish ] || [ $GOAL = route ] || [ $GOAL = grt ]; }; then python3 -I /work/kit_modes.py check /work --step grt --session 'tc bc' --hold-repair || rc=9; if [ \$rc = 0 ]; then \$M grt HOLD_SLACK_MARGIN=\$HM; rc=\$?; fi; if [ \$rc != 0 ]; then echo 'per-mode GRT hold repair (tc TT setup / BC FF hold) failed'; fi; elif [ \$rc = 0 ] && [ -n \"\$HM\" ] && [ -n \"\$VF\" ] && { [ $GOAL = finish ] || [ $GOAL = route ] || [ $GOAL = grt ]; }; then python3 -I /work/kit_modes.py check /work --step grt --session bc --vclk-corner ff --hold-repair || rc=9; if [ \$rc = 0 ]; then OT_VCLK_CORNER=ff \$M grt CORNER=BC CORNERS=bc HOLD_SLACK_MARGIN=\$HM; rc=\$?; fi; if [ \$rc != 0 ]; then echo 'FF-only GRT hold repair (FF vclk frame) failed'; fi; fi; \
  if [ \$rc = 0 ] && { [ $GOAL = finish ] || [ $GOAL = route ]; }; then python3 -I /work/legacy_gate.py /work grt; rc=\$?; fi; \
  if [ \$rc = 0 ]; then \$M $GOAL; rc=\$?; fi; \
  if [ \$rc = 0 ] && { [ $GOAL = route ] || [ $GOAL = finish ]; }; then \$M do-finish && \$M do-generate_abstract; rc=\$?; fi; \
  if [ \$rc = 0 ] && [ $GOAL = place ]; then P=\$(ls /work/run/results/asap7/*/base/3_place.odb | tail -1); ODB=\$P OUT=/work/placed.csv openroad -python -exit /work/dump_placed.py > /work/dump_placed.log 2>&1; fi; \
  O=\$(ls /work/run/results/asap7/*/base/5_route.odb /work/run/results/asap7/*/base/6_final.odb 2>/dev/null | tail -1); \
  if [ -n \"\$O\" ]; then ODB=\$O PINS=/work/pins.json OUT=/work/pin_audit.json openroad -python -exit /work/pin_audit.py; fi; \
  F=\$(ls /work/run/results/asap7/*/base/6_final.odb 2>/dev/null | tail -1); \
  if [ -n \"\$F\" ]; then for c in TT FF; do OT_CORNER=\$c DESIGN_NAME=$TOP ODB=\$F SPEF=\${F%.odb}.spef openroad -exit /work/corners.tcl > /work/sta_\$c.log 2>&1; done; fi; \
  if { [ -f /work/lec_async.on ] || [ -f /work/lec_async.identity ]; }; then bash /work/lec_async.sh wait /work '$NAME' '$GOAL' \$rc; fi; chown -R \$HUID:\$HGID /work; exit \$rc" > "$K/run_$GOAL.log" 2>&1
rc=$?
[ -z "$LECA" ] || rc=$(bash "$K/lec_async.sh" finish "$K" "$rc" 1 "$NAME" "$GOAL")
$DOCKER run --rm -v "$K":/work "$IMAGE" chown -R $(id -u):$(id -g) /work >/dev/null 2>&1
echo "end $(date -Is) rc $rc" >> "$K/image.txt"
tail -5 "$K/run_$GOAL.log"
# SIGNOFF (main f942bf2f72): uniform verdict in KIT/signoff/signoff.json; a core is closed only when it says SIGNED.
if [ $rc = 0 ] && { [ $GOAL = route ] || [ $GOAL = finish ]; }; then
  if [ ! -f "$K/signoff.py" ]; then
    echo "SIGNOFF FAIL: missing $K/signoff.py" >&2
    rc=4
  else
  SIGNOFF_DOCKER="$DOCKER" python3 -I "$K/signoff.py" run --run-dir "$K/run" --kit "$K" --corners tt,ff \
    --out "$K/signoff" --image "$IMAGE" > "$K/signoff.log" 2>&1
  rc=$?
  grep -E '^SIGNOFF|^  - ' "$K/signoff.log" | head -12
  fi
fi
exit $rc
